// RITEALMAR - Fase 6
// Calcula el resumen comercial diario a partir de la hoja "Empresas".

const rows = $input.all().map(item => item.json);

// -------------------------------------------------------
// UTILIDADES
// -------------------------------------------------------

const texto = (valor) =>
  String(valor ?? '').trim();

const normalizar = (valor) =>
  texto(valor)
    .toLowerCase()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '');

// Fecha actual usando horario de España
const partesHoy = new Intl.DateTimeFormat('es-ES', {
  timeZone: 'Europe/Madrid',
  day: '2-digit',
  month: '2-digit',
  year: 'numeric',
}).formatToParts(new Date());

const getParte = (tipo) =>
  partesHoy.find(p => p.type === tipo)?.value || '';

const hoy = `${getParte('day')}/${getParte('month')}/${getParte('year')}`;

// Convierte dd/MM/yyyy o dd/MM/yyyy HH:mm:ss a número comparable YYYYMMDD
function fechaNumero(valor) {
  const str = texto(valor);

  if (!str) return null;

  const match = str.match(
    /^(\d{1,2})\/(\d{1,2})\/(\d{4})/
  );

  if (!match) return null;

  const dia = Number(match[1]);
  const mes = Number(match[2]);
  const anio = Number(match[3]);

  if (
    !dia ||
    !mes ||
    !anio ||
    dia < 1 ||
    dia > 31 ||
    mes < 1 ||
    mes > 12
  ) {
    return null;
  }

  return (anio * 10000) + (mes * 100) + dia;
}

const hoyNumero = fechaNumero(hoy);

// -------------------------------------------------------
// EXCLUIR REGISTROS DE PRUEBA
// -------------------------------------------------------

function esRegistroPrueba(row) {
  const empresa = normalizar(row['Empresa']);
  const persona = normalizar(row['Persona contacto']);
  const email = normalizar(row['Email']);
  const notas = normalizar(row['Notas']);

  const textoCompleto = `${empresa} ${persona} ${email} ${notas}`;

  const palabrasPrueba = [
    'empresa demo',
    'auditoria demo',
    'empresa test',
    'prueba ritealmar',
    'prueba autorespuesta',
    'post webhook ritealmar',
  ];

  if (palabrasPrueba.some(p => textoCompleto.includes(p))) {
    return true;
  }

  // Cuenta utilizada en pruebas internas
  if (email === 'ritealmar.ai@gmail.com') {
    return true;
  }

  return false;
}

const leads = rows.filter(row => !esRegistroPrueba(row));

// -------------------------------------------------------
// CLASIFICACIONES
// -------------------------------------------------------

function estaBloqueado(row) {
  const estado = normalizar(row['Estado']);
  const respuesta = normalizar(row['Respuesta']);

  return (
    estado === 'no contactar' ||
    estado === 'email con rebote' ||
    respuesta === 'rebote'
  );
}

function tieneRespuestaReal(row) {
  const respuesta = normalizar(row['Respuesta']);

  return respuesta === 'respondio';
}

function tieneReunion(row) {
  return (
    normalizar(row['Calendly']) === 'si' ||
    normalizar(row['Estado']) === 'reunion agendada'
  );
}

function seguimientoValido(row) {
  const fecha = fechaNumero(row['Próximo Seguimiento']);

  if (!fecha) return false;
  if (estaBloqueado(row)) return false;
  if (tieneRespuestaReal(row)) return false;
  if (tieneReunion(row)) return false;

  return true;
}

// -------------------------------------------------------
// MÉTRICAS
// -------------------------------------------------------

const nuevosHoy = leads.filter(
  row => fechaNumero(row['Fecha Alta']) === hoyNumero
);

const respuestasHoy = leads.filter(row =>
  tieneRespuestaReal(row) &&
  fechaNumero(row['Fecha Actualización']) === hoyNumero
);

const rebotesHoy = leads.filter(row => {
  const respuesta = normalizar(row['Respuesta']);
  const estado = normalizar(row['Estado']);

  return (
    (respuesta === 'rebote' || estado === 'email con rebote') &&
    fechaNumero(row['Fecha Actualización']) === hoyNumero
  );
});

const reunionesHoy = leads.filter(row =>
  tieneReunion(row) &&
  fechaNumero(row['Fecha Actualización']) === hoyNumero
);

const seguimientosHoy = leads.filter(row =>
  seguimientoValido(row) &&
  fechaNumero(row['Próximo Seguimiento']) === hoyNumero
);

const seguimientosAtrasados = leads.filter(row =>
  seguimientoValido(row) &&
  fechaNumero(row['Próximo Seguimiento']) < hoyNumero
);

// -------------------------------------------------------
// PRIORIDAD COMERCIAL
// -------------------------------------------------------

function puntuacion(row) {
  let puntos = 0;

  const estado = normalizar(row['Estado']);
  const prioridad = normalizar(row['Prioridad']);
  const interes = normalizar(row['Interés']);
  const respuesta = normalizar(row['Respuesta']);
  const fechaSeguimiento = fechaNumero(row['Próximo Seguimiento']);

  if (tieneReunion(row)) puntos += 100;

  if (respuesta === 'respondio') {
    puntos += 80;
  }

  if (interes === 'alto') {
    puntos += 40;
  }

  if (prioridad === 'alta') {
    puntos += 30;
  }

  if (
    fechaSeguimiento &&
    fechaSeguimiento < hoyNumero &&
    seguimientoValido(row)
  ) {
    puntos += 50;
  }

  if (
    fechaSeguimiento &&
    fechaSeguimiento === hoyNumero &&
    seguimientoValido(row)
  ) {
    puntos += 40;
  }

  if (estado === 'nuevo') {
    puntos += 10;
  }

  if (estaBloqueado(row)) {
    puntos = -1000;
  }

  return puntos;
}

const prioridades = leads
  .map(row => ({
    empresa: texto(row['Empresa']),
    email: texto(row['Email']),
    telefono: texto(row['Teléfono']),
    estado: texto(row['Estado']),
    prioridad: texto(row['Prioridad']),
    respuesta: texto(row['Respuesta']),
    interes: texto(row['Interés']),
    proximo_seguimiento: texto(row['Próximo Seguimiento']),
    servicio: texto(row['Servicio recomendado']),
    puntuacion: puntuacion(row),
  }))
  .filter(row => row.puntuacion > 0)
  .sort((a, b) => b.puntuacion - a.puntuacion)
  .slice(0, 10);

// -------------------------------------------------------
// ACCIÓN RECOMENDADA
// -------------------------------------------------------

let accionRecomendada =
  'No hay respuestas, reuniones ni seguimientos pendientes para hoy. Prioriza los leads de prioridad alta que siguen sin respuesta y continúa la prospección comercial.';

if (reunionesHoy.length > 0) {
  accionRecomendada =
    'Prepara primero las reuniones agendadas y revisa el contexto de cada lead antes de la llamada.';
} else if (respuestasHoy.length > 0) {
  accionRecomendada =
    'Responde primero a los leads que han contestado e intenta convertir esas conversaciones en reuniones.';
} else if (seguimientosAtrasados.length > 0) {
  accionRecomendada =
    'Resuelve primero los seguimientos atrasados para evitar perder oportunidades comerciales.';
} else if (seguimientosHoy.length > 0) {
  accionRecomendada =
    'Realiza primero los seguimientos previstos para hoy.';
} else if (nuevosHoy.length > 0) {
  accionRecomendada =
    'Revisa primero los nuevos leads de hoy, prioriza los de mayor potencial y realiza el primer contacto comercial.';
}

// -------------------------------------------------------
// TEXTO DEL RESUMEN
// -------------------------------------------------------

const listaPrioridades = prioridades.length
  ? prioridades
      .slice(0, 5)
      .map((p, index) =>
        `${index + 1}. ${p.empresa} — ${p.estado || 'Sin estado'} — ${p.prioridad || 'Sin prioridad'}`
      )
      .join('\n')
  : 'Sin leads prioritarios pendientes.';

const resumenTexto = `📊 RITEALMAR — RESUMEN COMERCIAL DIARIO
Fecha: ${hoy}

CRM
• Leads reales totales: ${leads.length}
• Nuevos leads hoy: ${nuevosHoy.length}
• Respuestas hoy: ${respuestasHoy.length}
• Rebotes hoy: ${rebotesHoy.length}
• Reuniones agendadas hoy: ${reunionesHoy.length}
• Seguimientos para hoy: ${seguimientosHoy.length}
• Seguimientos atrasados: ${seguimientosAtrasados.length}

🔥 PRIORIDAD COMERCIAL
${listaPrioridades}

🎯 ACCIÓN RECOMENDADA
${accionRecomendada}`;

// -------------------------------------------------------
// DEVOLVER UN SOLO ITEM
// -------------------------------------------------------

return [
  {
    json: {
      fecha: hoy,

      leads_totales: leads.length,
      nuevos_hoy: nuevosHoy.length,
      respuestas_hoy: respuestasHoy.length,
      rebotes_hoy: rebotesHoy.length,
      reuniones_hoy: reunionesHoy.length,
      seguimientos_hoy: seguimientosHoy.length,
      seguimientos_atrasados: seguimientosAtrasados.length,

      prioridades,

      accion_recomendada: accionRecomendada,

      resumen_texto: resumenTexto,
    },
  },
];
